def transform_union_first(grid):
    """For each output row and column, take the union of ALL bands' non-zero values, pick first"""
    w, h = len(grid[0]), len(grid)
    output = []

    for row_idx in range(3):
        out_row = []
        for c in range(w):
            all_vals = set()
            for band_start in [0, 3, 6, 9]:
                for r in range(band_start, min(band_start + 3, h)):
                    if r < h and grid[r][c] != 0:
                        all_vals.add(grid[r][c])
            if all_vals:
                # Sort deterministically and pick first
                out_row.append(min(all_vals))
            else:
                out_row.append(0)
        output.append(out_row)
    return output

